function length(x: string | string[]) {
  x.length;   // ✓ — both string and string[] have length
  x.push("");  // Error — string has no push
  x.trim();   // Error — string[] has no trim
}

const id: string | number = fetchId();
id.toUpperCase();  // Error: toUpperCase doesn't exist on string | number
id.toString();    // ✓ — both members have toString

type Status = "idle" | "loading" | "error";

declare function setStatus(s: Status): void;

setStatus("loading");   // ✓
setStatus("Loading");   // Error — capital L isn't in the union
setStatus("fail");     // Error — typo caught at compile time

// Direction of control:
type Method = "GET" | "POST" | "PATCH" | "DELETE";

// Combined with booleans and null for state machines:
type Toggle = "on" | "off" | null;

// 1. typeof — for primitives
function size(x: string | number) {
  if (typeof x === "string") {
    return x.length;   // x: string here
  }
  return x.toString().length;  // x: number here (the only member left)
}

// 2. in — property presence, for object shapes
interface Admin { permissions: string[] }
interface Member { joinedAt: string }
function describe(user: Admin | Member) {
  if ("permissions" in user) {
    return `admin: ${user.permissions.length} perms`;  // user: Admin
  }
  return `member since ${user.joinedAt}`;               // user: Member
}

// 3. instanceof — for classes and built-ins
function parse(input: string | Date) {
  if (input instanceof Date) return input.toISOString();
  return new Date(input).toISOString();
}

// 4. Equality against a literal — for literal unions
function icon(s: "idle" | "loading" | "error") {
  if (s === "idle") return "▶";      // s: "idle"
  if (s === "loading") return "…";   // s: "loading"
  return "!";                         // s: "error" — everything else eliminated

// API responses as a discriminated union:
type FetchResult<T> =
  | { status: "ok"; data: T }
  | { status: "error"; message: string; retry: boolean };

function render<T>(result: FetchResult<T>) {
  switch (result.status) {
    case "ok":    return show(result.data);                    // T available
    case "error": return showError(result.message, result.retry);
  }
}

interface User { readonly id: number; email: string; role?: string }

// The predicate return type makes this a narrowing check the compiler trusts
function isUser(value: unknown): value is User {
  return (
    typeof value === "object" && value !== null &&
    "id" in value && typeof value.id === "number" &&
    "email" in value && typeof value.email === "string"
  );
}

const payload: unknown = await response.json();
if (isUser(payload)) {
  payload.email.toUpperCase();   // ✓ — payload narrowed to User
} else {
  reject("Invalid user payload");
}

