type Message =
  | { type: "text"; body: string }
  | { type: "file"; url: string; sizeKb: number }
  | { type: "payment"; amount: number; currency: "INR" | "USD" }
  | { type: "system"; level: "info" | "warn" };

function describe(msg: Message): string {
  switch (msg.type) {
    case "text":    return `text: ${msg.body.slice(0, 20)}`;
    case "file":    return `file: ${msg.sizeKb} KB`;
    case "payment": return `payment: ${msg.amount} ${msg.currency}`;
    case "system":  return `system: ${msg.level}`;
    default: {
      const unreachable: never = msg;   // errors if any member missed
      return unreachable;
    }
  }
}
